            mermaid: 'graph TD\n  A["Inicializar k centroides\\n(aleatorio)"] --> B["Asignar cada ejemplo\\nal centroide más cercano"]\n  B --> C["Recalcular cada centroide\\ncomo promedio de sus asignados"]\n  C --> D{"¿Los centroides\\ndejaron de moverse?"}\n  D -->|No| B\n  D -->|Sí| E["Grupos finales"]',
